<template>
  <div class="landing-page">
    <div class="wrapper">
      <div class="section section-hero section-shaped">
        <div class="shape shape-style-3 page-header-image argo-service-header">
          <span class="span-150"></span>
          <span class="span-50"></span>
          <span class="span-50"></span>
          <span class="span-75"></span>
          <span class="span-100"></span>
          <span class="span-75"></span>
          <span class="span-50"></span>
          <span class="span-100"></span>
          <span class="span-50"></span>
          <span class="span-100"></span>
        </div>
        <div class="page-header">
          <div
            class="container shape-container d-flex align-items-center py-lg"
          >
            <div class="col px-0">
              <div class="row align-items-center justify-content-center">
                <div class="col-lg-6 text-center">
                  <h1 class="text-white display-1">
                    {{ $t("APP.COMPONENTS.PHOTOS.TITLE") }}
                  </h1>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="separator separator-bottom separator-skew zindex-100">
          <svg
            x="0"
            y="0"
            viewBox="0 0 2560 100"
            preserveAspectRatio="none"
            version="1.1"
            xmlns="http://www.w3.org/2000/svg"
          >
            <polygon
              class="fill-sfondo"
              points="2560 0 2560 100 0 100"
            ></polygon>
          </svg>
        </div>
      </div>
    </div>
    <section>
      <div class="lightbox-gallery">
        <div class="container">
          <div class="intro">
            <h2 class="text-center"></h2>
            <p class="text-center">
            </p>
          </div>
          <div class="row photos">
            <div class="col-sm-6 col-md-4 col-lg-3 item"  v-for="(imgPath,index) in photosLowResolution" v-bind:key="index">
              <img
                @click="showSingle(index)"
                class="img-fluid cursor-pnt argo-img"
                :src="pathHREF + imgPath"
              />
            </div>
          </div>
        </div>
      </div>
      <vue-easy-lightbox
        :visible="visible"
        :imgs="imgs"
        :index="index"
        @hide="handleHide"
      >
      </vue-easy-lightbox>
    </section>
  </div>
</template>

<script lang="ts">
import { Component, Vue } from "vue-property-decorator";
import VueEasyLightbox from 'vue-easy-lightbox';

@Component({
  components: {
    VueEasyLightbox
  }
})
export default class PhotosView extends Vue {
    private visible: boolean = false;
    private index: number = 0;
    private imgs: String = ''

    private pathHREF: String = '../';
    private folderPhotoLowResolution: String = "studio";
    private folderPhotoHighResolution: String = "studio_original";
    private photoName: any[] = [
      "argo_studio_02.jpg",
"argo_studio_03.jpg",
"argo_studio_04.jpg",
"argo_studio_05.jpg",
"argo_studio_06.jpg",
"argo_studio_07.jpg",
"argo_studio_08.jpg",
"argo_studio_09.jpg",
"argo_studio_10.jpg",
"argo_studio_11.jpg",
"argo_studio_12.jpg",
"argo_studio_14.jpg",
"argo_studio_15.jpg",
"argo_studio_17.jpg",
"argo_studio_18.jpg",
"argo_studio_19.jpg",
"argo_studio_23.jpg",
"argo_studio_24.jpg",
"argo_studio_25.jpg",
"argo_studio_20.jpg",
"argo_studio_22.jpg",
"argo_studio_21.jpg",
"argo_studio_13.jpg",
"argo_studio_16.jpg",
"Oscar_Pongolini.jpg",
"Alberto_Cafulli.jpg",
"Lorenzo_Bassani.jpg"
    ];

    private photosLowResolution: any[] = [];
    private photosHighResolution: any[] = [];

    created() {
      this.initPhotoSourceArray();
    }

    initPhotoSourceArray() {
      this.photoName.forEach(name => {
        this.photosLowResolution.push("assets/img/" + this.folderPhotoLowResolution + "/" + name);
        this.photosHighResolution.push("assets/img/" + this.folderPhotoHighResolution + "/" + name);
      });
    }

    showSingle(index: number) {
      this.imgs = this.photosHighResolution[index];
      this.visible = true;
    }

    handleHide() {
       this.visible = false;
    }
}
</script>

<style scoped>
